#ifndef CSM_TERM_H
#define CSM_TERM_H

#include <stddef.h>

enum key_code {
	KEY_NONE,		/* consumed, means nothing (unknown sequence) */
	KEY_CHAR,		/* text holds one UTF-8 character */
	KEY_UP,
	KEY_DOWN,
	KEY_LEFT,
	KEY_RIGHT,
	KEY_PAGE_UP,
	KEY_PAGE_DOWN,
	KEY_HOME,
	KEY_END,
	KEY_ENTER,
	KEY_TAB,
	KEY_BACKTAB,
	KEY_ESC,
	KEY_BACKSPACE,
	KEY_DELETE,
	KEY_CTRL,		/* text holds the letter: "u" for Ctrl-U */
	KEY_MOUSE,
	KEY_BACKGROUND		/* the terminal's answer: dark says which */
};

enum mouse_event {
	MOUSE_PRESS,
	MOUSE_RELEASE,
	MOUSE_DRAG,		/* moved with a button held */
	MOUSE_WHEEL_UP,
	MOUSE_WHEEL_DOWN
};

/* Modifiers of a mouse event, when the terminal passes them on. */
#define MOD_SHIFT 1
#define MOD_ALT 2
#define MOD_CTRL 4

struct key {
	enum key_code code;
	char text[5];
	enum mouse_event mouse;	/* the rest is for KEY_MOUSE only */
	int button;		/* 0 left, 1 middle, 2 right */
	unsigned mods;
	size_t x, y;		/* the cell, from 0 */
	long ms;		/* when it came, for double clicks */
	int dark;		/* KEY_BACKGROUND: 1 dark, 0 light */
};

/* What term_wait saw. */
enum term_event {
	TERM_INPUT,
	TERM_TIMEOUT,
	TERM_RESIZE,		/* also after a stop: the screen needs a redraw */
	TERM_ERROR
};

size_t key_decode(const unsigned char *buf, size_t len, int more,
    struct key *k);

int term_open(void);
void term_close(void);
int term_size(size_t *cols, size_t *rows);
int term_write(const char *s, size_t len);
enum term_event term_wait(int timeout_ms);
size_t term_read(unsigned char *buf, size_t size);

#endif
